"use client";

// Account administration (UC-19; FR-24, FR-25, FR-38). Individual accounts only, no
// self-registration. Temporary passwords are generated by the server and shown ONCE here;
// they are not stored by the browser. Disabling, role changes and resets revoke sessions.
import { useActionState, useState } from "react";
import { createAccount, updateAccount } from "@/app/actions/admin";
import { FormMessage, INPUT_CLS, SubmitButton } from "@/components/forms";
import { Badge, DateTime } from "@/components/overview/badge";
import { ROLE_LABEL, type Role } from "@/lib/accounts";
import type { AdminAccount } from "@/lib/admin-types";
import { INITIAL_FORM_STATE, type FormState } from "@/lib/form-state";

const ROLES: Role[] = ["supervisor", "admin", "admin_supervisor"];

function OneTimeSecret({ state }: { state: FormState }) {
  const [copied, setCopied] = useState(false);
  if (!state.ok || !state.secret) return null;
  return (
    <div role="status" className="space-y-1 rounded-lg border border-amber-300 bg-amber-50 p-3 text-sm">
      <p className="font-medium text-amber-900">Temporary password (shown once)</p>
      <div className="flex flex-wrap items-center gap-2">
        <code className="rounded bg-white px-2 py-1 font-mono text-sm select-all">{state.secret}</code>
        <button
          type="button"
          onClick={() => navigator.clipboard?.writeText(state.secret ?? "").then(() => setCopied(true), () => undefined)}
          className="rounded-md border border-amber-300 bg-white px-2 py-1 text-xs hover:bg-amber-100"
        >
          {copied ? "Copied" : "Copy"}
        </button>
      </div>
      <p className="text-xs text-amber-900">
        Give it to the person directly, not by a shared channel. It is not stored in readable form and cannot be shown
        again; reset the password if it is lost.
      </p>
    </div>
  );
}

function CreateAccountForm() {
  const [state, action, pending] = useActionState(createAccount, INITIAL_FORM_STATE);
  const keep = state.ok ? undefined : state.values;
  return (
    <section aria-labelledby="create-acc-heading" className="space-y-3 rounded-xl border border-slate-200 bg-white p-4 shadow-sm">
      <h2 id="create-acc-heading" className="font-semibold">
        Create account
      </h2>
      <form key={state.seq} action={action} className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
        <div className="space-y-1 lg:col-span-1">
          <label htmlFor="acc-email" className="block text-xs font-medium text-slate-700">
            Email address
          </label>
          <input id="acc-email" name="email" type="email" required maxLength={254} autoComplete="off" defaultValue={keep?.email ?? ""} className={INPUT_CLS} />
        </div>
        <div className="space-y-1">
          <label htmlFor="acc-name" className="block text-xs font-medium text-slate-700">
            Display name
          </label>
          <input id="acc-name" name="displayName" required maxLength={100} autoComplete="off" defaultValue={keep?.displayName ?? ""} className={INPUT_CLS} />
        </div>
        <div className="space-y-1">
          <label htmlFor="acc-role" className="block text-xs font-medium text-slate-700">
            Role
          </label>
          <select id="acc-role" name="role" defaultValue={keep?.role ?? "supervisor"} className={INPUT_CLS}>
            {ROLES.map((r) => (
              <option key={r} value={r}>
                {ROLE_LABEL[r]}
              </option>
            ))}
          </select>
        </div>
        <div className="flex items-end">
          <SubmitButton pending={pending}>Create account</SubmitButton>
        </div>
      </form>
      <FormMessage state={state} />
      <OneTimeSecret state={state} />
    </section>
  );
}

function AccountRow({ a, isSelf }: { a: AdminAccount; isSelf: boolean }) {
  const [state, action, pending] = useActionState(updateAccount, INITIAL_FORM_STATE);
  const [confirm, setConfirm] = useState<"disable" | "reset" | null>(null);

  return (
    <li className="space-y-2 py-3">
      <div className="flex flex-wrap items-start justify-between gap-2">
        <div className="min-w-0">
          <p className="font-medium">
            {a.displayName} {isSelf && <span className="text-xs font-normal text-slate-500">(you)</span>}
          </p>
          <p className="truncate text-xs text-slate-500">{a.email}</p>
          <p className="text-xs text-slate-500">
            Last sign-in: {a.lastSignIn ? <DateTime iso={a.lastSignIn} /> : "never"} · created <DateTime iso={a.createdAt} />
          </p>
        </div>
        <div className="flex flex-wrap items-center gap-1">
          <Badge tone="info">{ROLE_LABEL[a.role]}</Badge>
          {a.enabled ? <Badge tone="ok">Enabled</Badge> : <Badge tone="muted">Disabled</Badge>}
        </div>
      </div>

      <div className="flex flex-wrap items-center gap-2">
        <form action={action} className="flex items-center gap-1">
          <input type="hidden" name="accountId" value={a.id} />
          <input type="hidden" name="op" value="role" />
          <label htmlFor={`role-${a.id}`} className="sr-only">
            Role for {a.displayName}
          </label>
          <select id={`role-${a.id}`} name="role" defaultValue={a.role} disabled={isSelf} className={`${INPUT_CLS} w-auto py-1 text-xs`}>
            {ROLES.map((r) => (
              <option key={r} value={r}>
                {ROLE_LABEL[r]}
              </option>
            ))}
          </select>
          {!isSelf && (
            <button type="submit" disabled={pending} className="rounded-md border border-slate-300 bg-white px-2 py-1 text-xs hover:bg-slate-50 disabled:opacity-50">
              Change role
            </button>
          )}
        </form>

        {a.enabled ? (
          !isSelf && (
            <button type="button" onClick={() => setConfirm("disable")} className="rounded-md border border-red-300 bg-white px-2 py-1 text-xs text-red-700 hover:bg-red-50">
              Disable…
            </button>
          )
        ) : (
          <form action={action}>
            <input type="hidden" name="accountId" value={a.id} />
            <input type="hidden" name="op" value="enable" />
            <button type="submit" disabled={pending} className="rounded-md border border-slate-300 bg-white px-2 py-1 text-xs hover:bg-slate-50 disabled:opacity-50">
              Enable
            </button>
          </form>
        )}
        <button type="button" onClick={() => setConfirm("reset")} className="rounded-md border border-slate-300 bg-white px-2 py-1 text-xs hover:bg-slate-50">
          Reset password…
        </button>
      </div>

      {confirm && (
        <form action={action} className="flex flex-wrap items-center gap-2 rounded-md border border-slate-200 bg-slate-50 p-2 text-xs">
          <input type="hidden" name="accountId" value={a.id} />
          <input type="hidden" name="op" value={confirm} />
          <span>
            {confirm === "disable"
              ? `Disable ${a.displayName}? They are signed out everywhere and cannot sign in.`
              : `Reset the password for ${a.displayName}? They are signed out everywhere.`}
          </span>
          <SubmitButton pending={pending} variant="danger">
            {confirm === "disable" ? "Disable account" : "Reset password"}
          </SubmitButton>
          <button type="button" onClick={() => setConfirm(null)} className="text-slate-600 hover:underline">
            Cancel
          </button>
        </form>
      )}
      <FormMessage state={state} />
      <OneTimeSecret state={state} />
    </li>
  );
}

export function AccountsPage({ accounts, selfId }: { accounts: AdminAccount[]; selfId: string }) {
  return (
    <div className="mx-auto max-w-5xl space-y-6 px-4 py-6 md:px-8">
      <header>
        <h1 className="text-2xl font-semibold">Accounts</h1>
        <p className="text-sm text-slate-500">
          Individual accounts keep every response attributable. There is no self-registration. The last administrator
          cannot be disabled or demoted.
        </p>
      </header>
      <CreateAccountForm />
      <section aria-labelledby="acc-list-heading" className="rounded-xl border border-slate-200 bg-white p-4 shadow-sm">
        <h2 id="acc-list-heading" className="font-semibold">
          All accounts <span className="text-sm font-normal text-slate-500">({accounts.length})</span>
        </h2>
        <ul className="mt-1 divide-y divide-slate-100">
          {accounts.map((a) => (
            <AccountRow key={a.id} a={a} isSelf={a.id === selfId} />
          ))}
        </ul>
      </section>
    </div>
  );
}
